import assert from 'node:assert/strict';
import Anthropic from '@anthropic-ai/sdk';
import OpenAI from 'openai';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Open Autonomy's model rail (packages/backend/src/proxy.ts): every model call a worker's stock SDK makes is forwarded to
// Merge's Gateway with the platform's key, MODEL_GATEWAY_API_KEY, as a bearer token
const gateway = (process.env.MODEL_GATEWAY_URL ?? 'https://api-gateway.merge.dev').replace(/\/$/, '');
const key = process.env.MODEL_GATEWAY_API_KEY ?? '';
// the twin runs no model: an unscripted turn is its labelled deterministic stub, asserted as a stub
const stub = (model, said) => `[twin-stub:${model}] This is a deterministic stub from the Merge Gateway twin (no model runs). Your last message: ${said}`;

// the catalog for an owner choosing a key's models (routes.ts, /v1/catalog): every page of GET /v1/models by its cursor
const ids = [], listed = [];
let cursor;
for (let page = 0; page < 40; page++) {
  const upstream = await fetch(`${gateway}/v1/models${cursor ? `?cursor=${encodeURIComponent(cursor)}` : ''}`, { headers: { authorization: `Bearer ${key}` } });
  assert.equal(upstream.status, 200, 'the catalog answers: ' + upstream.status);
  const body = await upstream.json();
  for (const m of body.data) { ids.push(m.model ?? m.id ?? m.name); listed.push(m); }
  if (!body.has_more || !body.next_cursor || body.next_cursor === cursor) break;
  cursor = body.next_cursor;
}
const HERMES = 'zai/glm-5.3-flash';
assert.ok(ids.includes(HERMES), 'the catalog lists the workers\' model: ' + ids.join(', '));
// an organization made after Anthropic's access cutoff (4 September 2026), as the World's is, sees Anthropic's models
// listed as access-required until support grants them
const haiku = listed.find((m) => m.model === 'anthropic/claude-haiku-4-5-20251001');
assert.ok(haiku && haiku.access_required === true && haiku.access_reason === 'vendor_access_required', 'a gated model stays visible: ' + JSON.stringify(haiku));

// the Hermes worker's turn (api_mode chat_completions, zai/glm-5.3-flash), streamed: the rail asks the stream's usage
// (stream_options.include_usage) and reads its cost to settle the account
const openai = new OpenAI({ apiKey: key, baseURL: `${gateway}/v1`, maxRetries: 0 });
const asked = 'Which of the ledger\'s open items can be reconciled today?';
const stream = await openai.chat.completions.create({ model: HERMES, max_tokens: 32000, stream: true, stream_options: { include_usage: true }, messages: [
  { role: 'system', content: 'You are the ledger worker of an Open Autonomy project.' },
  { role: 'user', content: asked },
] });
let text = '', finish, usage;
for await (const chunk of stream) {
  text += chunk.choices[0]?.delta?.content ?? '';
  finish = chunk.choices[0]?.finish_reason ?? finish;
  if (chunk.usage) usage = chunk.usage;
}
assert.equal(text, stub(HERMES, asked));
assert.equal(finish, 'stop');
assert.ok(usage.prompt_tokens > 0 && usage.completion_tokens > 0, 'the final chunk carries the usage: ' + JSON.stringify(usage));
assert.ok(typeof usage.cost === 'number' && usage.cost > 0, 'the usage carries the call\'s cost in USD: ' + JSON.stringify(usage));

// Claude Code's turn on the Anthropic wire (the rail passes anthropic-version) on the project's model, which carries its
// provider slug and so passes the rail unmapped: streamed with a tool, then its result
const CODE_MODEL = HERMES;
const anthropic = new Anthropic({ apiKey: null, authToken: key, baseURL: gateway, maxRetries: 0 });
const tools = [{ name: 'Read', description: 'Read a file from the repository.', input_schema: { type: 'object', properties: { file_path: { type: 'string' } }, required: ['file_path'] } }];
const task = 'Explain the retry in src/settle.ts.';
const turn = await anthropic.messages.stream({ model: CODE_MODEL, max_tokens: 32000, tools, messages: [{ role: 'user', content: task }] }).finalMessage();
assert.equal(turn.stop_reason, 'tool_use');
const call = turn.content.find((b) => b.type === 'tool_use');
assert.ok(call && call.name === 'Read' && typeof call.input.file_path === 'string', 'the stub calls the tool with input its schema allows: ' + JSON.stringify(turn.content));
assert.ok(turn.usage.input_tokens > 0 && turn.usage.output_tokens > 0, 'the stream carries the usage: ' + JSON.stringify(turn.usage));
const result = 'export async function settle(call) { for (let attempt = 0; attempt < 3; attempt++) { /* ... */ } }';
const answered = await anthropic.messages.stream({ model: CODE_MODEL, max_tokens: 32000, tools, messages: [
  { role: 'user', content: task },
  { role: 'assistant', content: turn.content },
  { role: 'user', content: [{ type: 'tool_result', tool_use_id: call.id, content: result }] },
] }).finalMessage();
assert.equal(answered.stop_reason, 'end_turn');
assert.equal(answered.content[0].type, 'text');
assert.ok(answered.content[0].text.startsWith(`[twin-stub:${CODE_MODEL}]`), 'after the tool result the stub answers in text: ' + JSON.stringify(answered.content));

console.log(JSON.stringify({ catalog: ids, hermes: text, cost: usage.cost, codeTool: call.name, code: answered.content[0].text }));
